	/**
	 * 選択されているShapeにより、リストの並び順を変更
	 *
	 */
	sortProductList4Shape(list, priority_shape) {
		var priority_list = [];
		var other_list = [];
		var item;
		for(var i=0,max=list.length; i<max; i++) {
			item = list[i];
			if (item['SHAPE'] == priority_shape) {
				priority_list.push(item);
			} else {
				other_list.push(item);
			}
		}

		return priority_list.concat(other_list);
	},


