	/**
	 * ステップフローの並び順変更
	 *
	 */
	setupFlowNavi: function() {
// console.log('setupFlowNavi() - start.');

		// ステップフロー情報の取得（シミュレーション開始画面IDごとに異なる）
		var flow_list = ENGINE.Simulator.flow_list['default'];


		// ステップフローの並び替え
		if (flow_list) {
			for(var i=0,max=flow_list.length; i<max; i++) {
				var target_id = flow_list[i]['id'];
				var $item = ENGINE.Simulator.flow_nav['items'][target_id];

				// Output選択画面（TOPページ）で該当パーツが選ばているかどうか、ステップフローの表示非表示を制御
				if ( (target_id == 'over-head-shower') || (target_id == 'hand-shower') || (target_id == 'bath-spout') ) {
// console.log('setupFlowNavi() list[' + target_id + '] condition[' + (ENGINE.Simulator.condition['is-' + target_id]) + ']');
					if (ENGINE.Simulator.condition['is-' + target_id]) {
						flow_list[i]['show'] = true;
					} else {
						flow_list[i]['show'] = false;
					}
				}

				// 表示非表示の切り替え
				if (flow_list[i]['show']) {
					$item.show();
				} else {
					$item.hide();
				}
				// リンクの非・アクティブ化
				ENGINE.Simulator.flow_nav['links'][target_id].addClass('is_inactive');

				ENGINE.Simulator.flow_nav['container'].append($item);
			}
		}
// console.log('setupFlowNavi() - end.');
	},
	/**
	 * ステップフローの更新（Active / InActiveの切り替え）
	 *
	 */
	resetFlowNavi: function(target_id, current_id) {
// console.log('resetFlowNavi() - start.');
// console.log('resetFlowNavi() : target[' + target_id + ']' + ' current[' + current_id + ']');

		// 1つめの画面遷移の場合、ステップフローを更新する（ステップが変更になるため）
		if ((ENGINE.Simulator.panel_history_list.length == 1) || (current_id == 'top')) {
// console.log(ENGINE.Simulator.condition);
			ENGINE.Simulator.setupFlowNavi(target_id);
		}

		// Activeにするステップを取得
		var $target = ENGINE.Simulator.flow_nav['items'][target_id];
		if ($target) {
			// リセット
			ENGINE.Simulator.flow_nav['all-items'].removeClass('is_current');
			// Active化
			$target.addClass('is_current');

			// フローリストの位置調整
			var $holder = $('.m_flow');
			var $move   = ENGINE.Simulator.flow_nav['container'];

			var holder_pos = $holder.offset().left;
			var holder_w   = $holder.width();
			var target_pos = $target.offset().left;
			var target_w   = $target.width();
			var pos = 0;

			pos = (target_pos + $holder.scrollLeft()) - holder_pos - (holder_w - target_w) / 2;

// console.log('resetFlowNavi() : current pos[' + target_pos + '] move pos[' + $move.offset().left + '] move pos[' + $holder.scrollLeft() + '] holder pos[' + holder_pos + ']');
// console.log('resetFlowNavi() : current pos[' + target_w + '] holder pos[' + holder_w + ']');
// console.log('resetFlowNavi() : pos[' + pos + ']');
			if (pos > 0) {
// console.log('resetFlowNavi() : adjust');
				$holder.scrollLeft(pos);
			}
		} else {
			ENGINE.Simulator.flow_nav['all-items'].removeClass('is_current');
		}

		// リンクの有効化
		for (var id in ENGINE.Simulator.condition) {
			if (ENGINE.Simulator.condition[id] && ENGINE.Simulator.flow_nav['links'][id]) {
				ENGINE.Simulator.flow_nav['links'][id].removeClass('is_inactive');
			}
		}

// console.log('resetFlowNavi() - end.');
	},
