	/**
	 * Output数の選択（TOPページ）
	 *
	 */
	initSelectOutput: function(is_reset) {
// console.log('initSelectOutput() - start.');
		is_reset = is_reset?is_reset:false;
// console.log('initSelectOutput() : is_reset[' + is_reset + ']');

		// var data  = {};
		var $holder = $('#select-output');
		var $icon1  = $('#select-output-icon1');
		var $icon2  = $('#select-output-icon2');

		$holder.find('input[type="checkbox"]').each(function() {
			var $input  = $(this);
			var $parent = $input.parent();
			//
			var target_id = $input.val();
			// data[target_id] = 0;

			// active化にしようするclassの定義
			var active_cls = 'is_' + target_id;

			// 対応する選択画像欄を格納
			var $panel = $('#select-output-' + target_id);


			// onchange時の処理
			// is_resetではない場合のみ、イベント設定を行う
			if (!is_reset) {
				$input.on('change', function() {
					if ($input.prop('checked')) {
						// data[target_id] = 1;
						$parent.addClass(active_cls);
						$panel.addClass(active_cls);
					} else {
						// data[target_id] = 0;
						$parent.removeClass(active_cls);
						$panel.removeClass(active_cls);
					}
					// 判定処理
					_judge();
				});

			// is_resetの場合、inputのcheckを外し、再度判断
			} else {
				$input.prop('checked', false);
				// data[target_id] = 0;
				$parent.removeClass(active_cls);
				$panel.removeClass(active_cls);

				_judge();
			}
		});

		function _judge() {
// console.log('initSelectOutput() - _judge() - start.');
// console.log(data);
			var data_over_head_shower = $holder.find('input[type="checkbox"][value="over-head-shower"]').prop('checked')?1:0;
			var data_hand_shower      = $holder.find('input[type="checkbox"][value="hand-shower"]').prop('checked')?1:0;
			var data_bath_spout       = $holder.find('input[type="checkbox"][value="bath-spout"]').prop('checked')?1:0;

			// 次へ進めるかどうか
			var output = 0;
			var is_invalid_select = false;
			var is_valid_next = false;
			// faucetのみはNG

			// アイコン（上）の表示切り替え
			// if (data_over_head_shower && (data_hand_shower || data_bath_spout)) {
			if (data_over_head_shower && (data_hand_shower)) {
				$icon1.addClass('is_select__icon1');
			} else {
				$icon1.removeClass('is_select__icon1');
			}
			// アイコン（下）の表示切り替え
			if (data_bath_spout && (data_over_head_shower || data_hand_shower)) {
				$icon2.addClass('is_select__icon2');
			} else {
				$icon2.removeClass('is_select__icon2');
			}

			// NextボタンおよびSpoutのみ選択の判定
			if (data_bath_spout) {
				if (data_hand_shower) {
					is_valid_next = true;
				} else if (data_over_head_shower) {
					is_valid_next = true;
				} else {
					is_invalid_select = true;
				}

			} if (data_over_head_shower || data_hand_shower) {
				is_valid_next = true;
			}

			// Spoutのみ選択時のエラー表示
			if (is_invalid_select) {
				$holder.addClass('is_invalid');
			} else {
				$holder.removeClass('is_invalid');
			}

			// Nextボタンの有効化
			if (is_valid_next) {
				$holder.addClass('is_select');
			} else {
				$holder.removeClass('is_select');
			}

			// output数の保存
			output = data_over_head_shower + data_hand_shower + data_bath_spout;
			ENGINE.Simulator.condition['output'] = output;

			// 選択されたOutputの種類の保存
			ENGINE.Simulator.condition['is-over-head-shower'] = data_over_head_shower;
			ENGINE.Simulator.condition['is-hand-shower'] = data_hand_shower;
			ENGINE.Simulator.condition['is-bath-spout'] = data_bath_spout;

// console.log('initSelectOutput() - _judge() : result[' + is_invalid_select + '][' + is_valid_next + ']');
// console.log('initSelectOutput() - _judge() - end.');

		}

// console.log('initSelectOutput() - end.');
	},
