	/**
	 * パーツごとの組み合わせNo、Series、Shapeの取得＆保存
	 *
	 */
	setConditionAttributesAt: function(parts_id) {

		var product_id, product, series, shape, combination_id;

		if (ENGINE.Simulator.condition[parts_id]) {
			product_id = ENGINE.Simulator.condition[parts_id];
			product    = ENGINE.Simulator.searchProductAt(parts_id, product_id);

			series = product['SERIES_CATEGORY'];
			shape  = product['SHAPE'];
			combination_id = product['COMBINATION_ID'];

			ENGINE.Simulator.condition[parts_id + '-combination'] = combination_id;
			ENGINE.Simulator.condition[parts_id + '-series'] = series;
			ENGINE.Simulator.condition[parts_id + '-shape']  = shape;

			// OverHeadShowerの場合、組み合わせNoが「OGR3W」かどうかの番団あり
			if (parts_id == 'over-head-shower') {
				ENGINE.Simulator.condition[parts_id + '-ogr3w']  = (combination_id == 'OGR3W')?'Y':'N';
			}
		} else {
			ENGINE.Simulator.condition[parts_id + '-combination'] = '';
			ENGINE.Simulator.condition[parts_id + '-series'] = '';
			ENGINE.Simulator.condition[parts_id + '-shape']  = '';
			if (parts_id == 'over-head-shower') {
				ENGINE.Simulator.condition[parts_id + '-ogr3w']  = 'N';
			}
		}
	},
