	/**
	 * お気に入りの保存
	 *
	 */
	addFavorite: function($link) {
		if ($link.hasClass('is-done')) {
			return false;
		}

		var now = new Date();

		var id = now.getTime();
		var datetime_y = now.getFullYear();
		var datetime_m = ENGINE.SimulatorCommon.zeroPadding((now.getMonth() + 1), 2);
		var datetime_d = ENGINE.SimulatorCommon.zeroPadding(now.getDate(), 2);
		var datetime_h = ENGINE.SimulatorCommon.zeroPadding(now.getHours(), 2);
		var datetime_i = ENGINE.SimulatorCommon.zeroPadding(now.getMinutes(), 2);

		var disp_datetime = datetime_y + '/' + datetime_m + '/' + datetime_d + ' ' + datetime_h + ':' + datetime_i;

		var selected_output           = ENGINE.Simulator.condition['output'];
		var selected_over_head_shower = ENGINE.Simulator.condition['over-head-shower'];
		var selected_hand_shower      = ENGINE.Simulator.condition['hand-shower'];
		var selected_bath_spout       = ENGINE.Simulator.condition['bath-spout'];
		var selected_controller       = ENGINE.Simulator.condition['controller'];
		var selected_valve1           = ENGINE.Simulator.condition['valve1'];
		var selected_valve2           = ENGINE.Simulator.condition['valve2'];
		var selected_accessory1       = ENGINE.Simulator.condition['accessory1'];
		var selected_accessory2       = ENGINE.Simulator.condition['accessory2'];
		var selected_accessory3       = ENGINE.Simulator.condition['accessory3'];
		var selected_pos              = ENGINE.Simulator.condition['controller-relation-no'];


		var params = {
			'id':   id,
			'dt':   disp_datetime,
			'oid':  selected_over_head_shower,
			'hid':  selected_hand_shower,
			'bid':  selected_bath_spout,
			'cid':  selected_controller,
			'v1id': selected_valve1,
			'v2id': selected_valve2,
			'a1id': selected_accessory1,
			'a2id': selected_accessory2,
			'a3id': selected_accessory3,
			'pos':  selected_pos,
		};

		var favorite_list = ENGINE.Simulator.getFavoriteList();

		if (favorite_list) {
			if (favorite_list.length >= 10) {
				// 先頭要素を削除
				favorite_list.shift();
			}
		} else {
			favorite_list = [];
		}
		favorite_list.push(params);
		$.cookie(ENGINE.Simulator.settings['cookie_id'], favorite_list, {expires: ENGINE.Simulator.settings['cookie_expired']});

		$link.addClass('is-done');

		ENGINE.Simulator.refreshFavorite();
	},

	/**
	 * 保存されているお気に入りデータを取得
	 *
	 */
	getFavoriteList: function() {
		var result = false;
		var favorite = $.cookie(ENGINE.Simulator.settings['cookie_id']);
		if (favorite) {
			result = favorite;
		}

		return result;
	},

	/**
	 * 保存されているお気に入りデータを取得
	 *
	 */
	getFavorite: function(select_id) {
		var favorite = false;
		var favorite_list = ENGINE.Simulator.getFavoriteList();

		if (favorite_list && (favorite_list.length > 0)) {
			var id;
			for(var i=0, max=favorite_list.length; i<max; i++) {
				id = favorite_list[i]['id'];
				if (id == select_id) {
					favorite = favorite_list[i];
					break;
				}
			}
		}

		return favorite;
	},


	/**
	 * 保存されているお気に入りデータの削除
	 *
	 */
	deleteFavorite: function(id) {

		var next_id = false;
		var favorite_list = ENGINE.Simulator.getFavoriteList();
		var new_favorite_list = [];
		if (favorite_list) {
			for(var i=0,max=favorite_list.length; i<max; i++) {
				if (favorite_list[i]['id'] != id) {
					new_favorite_list.push(favorite_list[i]);
				}
			}
			$.cookie(ENGINE.Simulator.settings['cookie_id'], new_favorite_list, {expires: ENGINE.Simulator.settings['cookie_expired']});
		}

		ENGINE.Simulator.refreshFavorite();

		if (new_favorite_list.length > 0) {
			next_id = new_favorite_list[0]['id'];
		}

		return next_id;

	},
