	generateCode4IconList: function(product, is_wrap) {

		var code_list = '';
		var code_tech_list = '';
		var code_design_list = '';
		var tech_list = ENGINE.Simulator.settings['technologies'];
		var tech_flg, tech;

		// 技術アイコン、デザインアイコン
		for(var idx in tech_list) {
			tech_flg = product['TECH_' + idx];
			tech = tech_list[idx];
			if (tech_flg) {
				code_tech_list += '<li><img src="' + ENGINE.Simulator.settings['icon_image'] + 'technologies/' + tech['id'] + '@2x.png" alt="' + tech['name'] + '"></li>';
			}
		}
		if ( product['AWARD_01'] && (product['AWARD_01'] != '') ) {
			code_design_list += '<li><img src="' + ENGINE.Simulator.settings['icon_image'] + 'award/' + product['AWARD_01'] + '@2x.png" alt="' + product['AWARD_01'] + '"></li>';
		}
		if ( product['AWARD_02'] && (product['AWARD_02'] != '') ) {
			code_design_list += '<li><img src="' + ENGINE.Simulator.settings['icon_image'] + 'award/' + product['AWARD_02'] + '@2x.png" alt="' + product['AWARD_02'] + '"></li>';
		}

		if (code_tech_list || code_design_list) {
			if (is_wrap) {
				code_list += '<ul class="m_list__inline m_list__icon is-taR m_mgr10">';
			}
			code_list += code_tech_list + code_design_list;
			if (is_wrap) {
				code_list += '</ul>';
			}
		}

		return code_list;
	},
