	/**
	 * 製品情報の取得
	 *
	 *
	 */
	searchProductAt: function(type, id) {
		// 製品データの取得（配列ではなく、オブジェクトから取得）
		var master = false;
		if (type == 'over-head-shower') {
			master = ENGINE.Simulator.vars['over_head_shower_master'];
		} else if (type == 'hand-shower') {
			master = ENGINE.Simulator.vars['hand_shower_master'];
		} else if (type == 'bath-spout') {
			master = ENGINE.Simulator.vars['bath_spout_master'];
		} else if (type == 'controller') {
			master = ENGINE.Simulator.vars['controller_master'];
		} else if (type == 'valve') {
			master = ENGINE.Simulator.vars['valve_master'];
		} else if (type == 'accessory') {
			master = ENGINE.Simulator.vars['accessory_master'];
		} else if (type == 'other') {
			master = ENGINE.Simulator.vars['other_master'];
		}

		var result = false;
		if (master && master[id]) {
			result = master[id];
		}

		return result;
	},
