	/**
	 * 結果表示用URLパラメータの生成
	 *
	 */
	generateURLParameter: function(data) {
// console.log('generateURLParameter() - start.');

		data = data?data:ENGINE.Simulator.condition;

		var param = [];

		var selected_over_head_shower = data['over-head-shower'];
		var selected_hand_shower      = data['hand-shower'];
		var selected_bath_spout       = data['bath-spout'];
		var selected_controller       = data['controller'];
		var selected_valve1           = data['valve1'];
		var selected_valve2           = data['valve2'];
		var selected_accessory1       = data['accessory1'];
		var selected_accessory2       = data['accessory2'];
		var selected_accessory3       = data['accessory3'];
		var selected_pos              = data['controller-relation-no'];
		var selected_output           = data['output'];

// console.log(data);

		if (selected_over_head_shower) {
			param.push('oid=' + selected_over_head_shower);
		}
		if (selected_hand_shower) {
			param.push('hid=' + selected_hand_shower);
		}
		if (selected_bath_spout) {
			param.push('bid=' + selected_bath_spout);
		}
		if (selected_controller) {
			param.push('cid=' + selected_controller);
		}
		if (selected_valve1) {
			param.push('v1id=' + selected_valve1);
		}
		if (selected_valve2) {
			param.push('v2id=' + selected_valve2);
		}
		if (selected_accessory1) {
			param.push('a1id=' + selected_accessory1);
		}
		if (selected_accessory2) {
			param.push('a2id=' + selected_accessory2);
		}
		if (selected_accessory3) {
			param.push('a3id=' + selected_accessory3);
		}
		if (selected_pos) {
			param.push('pos=' + selected_pos);
		}
		if (selected_output) {
			param.push('output=' + selected_output);
		}

		var qstr = '';
		if (param.length > 0) {
			qstr = '?' + param.join('&');
		}
// console.log('generateURLParameter() - end.');

		return qstr;
	},


